const int BUZZER = 8;
const int KEYS[] = {2, 3, 4, 5};
const int NOTES[] = {262, 330, 392, 523};

void setup() {
  for (int i = 0; i < 4; i++) {
    pinMode(KEYS[i], INPUT_PULLUP);
  }
}

void loop() {
  int played = -1;
  for (int i = 0; i < 4; i++) {
    if (digitalRead(KEYS[i]) == LOW) played = i;
  }
  if (played >= 0) {
    tone(BUZZER, NOTES[played]);
  } else {
    noTone(BUZZER);
  }
}

