const int FSR_PIN = A0;
const int LEDS[] = {11, 12, 13};

void setup() {
  for (int i = 0; i < 3; i++) {
    pinMode(LEDS[i], OUTPUT);
  }
  Serial.begin(9600);
}

void loop() {
  int force = analogRead(FSR_PIN);
  int level = map(force, 0, 1023, 0, 3);
  for (int i = 0; i < 3; i++) {
    digitalWrite(LEDS[i], i < level ? HIGH : LOW);
  }
  Serial.println(force);
  delay(100);
}

const int TRIG = 9;
const int ECHO = 10;
const int BUZZER = 8;

void setup() {
  pinMode(TRIG, OUTPUT);
  pinMode(ECHO, INPUT);
  Serial.begin(9600);
}

void loop() {
  digitalWrite(TRIG, HIGH);
  delayMicroseconds(10);
  digitalWrite(TRIG, LOW);
  long echo = pulseIn(ECHO, HIGH);
  int cm = echo / 58;
  Serial.println(cm);
  if (cm < 50) {
    tone(BUZZER, 880, 60);
    delay(cm * 8);
  }
  delay(60);
}
